create or replace function private.sync_card_invoice_final(p_household_id uuid,p_card_id uuid,p_period text) returns void language plpgsql security definer set search_path='' as $$ declare v_total numeric:=0;v_invoice_id uuid;v_status text;begin if p_card_id is null or p_period is null then return;end if;select coalesce(sum(t.amount),0) into v_total from public.transactions t where t.household_id=p_household_id and t.card_id=p_card_id and t.type='DESPESA' and public.card_invoice_period(p_card_id,t.date)=p_period;select id,status::text into v_invoice_id,v_status from public.invoices where household_id=p_household_id and card_id=p_card_id and period=p_period limit 1;if v_total>0 then if v_invoice_id is null then insert into public.invoices(household_id,card_id,period,total,status) values(p_household_id,p_card_id,p_period,v_total,'ABERTA');else update public.invoices set total=v_total,updated_at=now() where id=v_invoice_id;end if;elsif v_invoice_id is not null and v_status<>'PAGA' then delete from public.invoices where id=v_invoice_id;end if;end $$;